export function createAuroraUI({cloud,toast,beforeOpen,onClose,onMusic}){
 const shell=document.createElement('section');shell.id='aurora-world';shell.hidden=true;shell.setAttribute('aria-label','公共极光雪境');document.body.append(shell);let active=false,opening=false,frame=null,epoch=0,waiter=null;
 const send=type=>frame?.contentWindow?.postMessage({type},location.origin);
 window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==frame?.contentWindow)return;if(e.data?.type==='echoo-aurora-ready')waiter?.resolve();if(e.data?.type==='echoo-aurora-error')waiter?.reject(Error(e.data.message||'雪境暂时没有加载好'));if(e.data?.type==='echoo-aurora-home')close();if(e.data?.type==='echoo-aurora-music')onMusic?.();});
 async function open(){if(active||opening)return;opening=true;const token=++epoch;window.planetArrival?.start(false,'正在前往极光雪境');try{if(cloud){if(!await cloud.flush())return;await cloud.aurora({action:'join',room:'outside'});}beforeOpen();active=true;document.body.classList.add('in-aurora');frame=document.createElement('iframe');frame.title='极光雪境';frame.allow='autoplay';const ready=new Promise((resolve,reject)=>{waiter={resolve,reject}}),timeout=setTimeout(()=>waiter?.reject(Error('雪境加载超时，请稍后重试')),60000);frame.src='./aurora.html?embedded=1';shell.append(frame);shell.hidden=false;try{await ready;}finally{clearTimeout(timeout);waiter=null;}if(token!==epoch)return;}catch(e){toast(e.message||'暂时没有连接上雪境');await close();}finally{opening=false;await window.planetArrival?.finish();}}
 async function close(){if(!active&&!opening)return;const had=active;epoch++;waiter?.resolve();active=false;send('echoo-aurora-stop');frame?.remove();frame=null;shell.hidden=true;document.body.classList.remove('in-aurora');if(cloud)try{await cloud.aurora({action:'leave'})}catch{}if(had)onClose?.();}
 return {open,close,get active(){return active}};
}
